# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(shape(fold(gather(render(sift(raw))))))

